// O body do webhook de retomada deve trazer { link_vercel_atualizado: "..." }.
const item = $input.item.json;
const body = item.body || {};
item.link_vercel = body.link_vercel_atualizado || item.link_vercel;
item._msg_reapresentacao = `Prontinho, ${(item.nome || '').split(' ')[0]}! Ajustei conforme combinamos. 😊\n\nDá uma olhada de novo aqui: ${item.link_vercel}\n\nFicou como você queria?`;
return { json: item };
